ail(a){return"\u0633\u064a\u062a\u0645 \u062d\u0630\u0641 "+a+" \u0646\u0647\u0627\u0626\u064a\u064b\u0627 \u0648\u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 \u0639\u0646 \u0630\u0644\u0643. \u064a\u064f\u0633\u0645\u062d \u0628\u0630\u0644\u0643 \u0641\u0642\u0637 \u0625\u0630\u0627 \u0644\u0645 \u064a\u0643\u0646 \u0644\u0647\u0630\u0627 \u0627\u0644\u0637\u0628\u064a\u0628 \u0623\u064a \u062d\u0627\u0644\u0627\u062a\u060c \u0623\u0648 \u0625\u0630\u0627 \u0643\u0627\u0646 \u0647\u0630\u0627 \u0627\u0644\u0641\u0631\u0639 \u0644\u0627 \u064a\u0632\u0627\u0644 \u062c\u062f\u064a\u062f\u064b\u0627 \u2014 \u0648\u0625\u0644\u0627\u060c \u0642\u0645 \u0628\u0625\u0644\u063a\u0627\u0621 \u0627\u0644\u062a\u0641\u0639\u064a\u0644 \u0628\u062f\u0644\u0627\u064b \u0645\u0646 \u0630\u0644\u0643."},
gaim(){return"\u062a\u0645 \u062d\u0630\u0641 \u0627\u0644\u0637\u0628\u064a\u0628 \u0646\u0647\u0627\u0626\u064a\u064b\u0627."},
gUO(){return"\u062a\u0639\u0630\u0651\u0631 \u0627\u0644\u062a\u0623\u0643\u062f \u0628\u0623\u0645\u0627\u0646 \u0645\u0646 \u062d\u0633\u0627\u0628 \u0647\u0630\u0627 \u0627\u0644\u0637\u0628\u064a\u0628 \u0641\u064a Dentist Clinic \u2014 \u0633\u064a\u062a\u0645 \u0631\u0641\u0636 \u0627\u0644\u062d\u0630\u0641."},
gaid(){return"\u0625\u0644\u063a\u0627\u0621 \u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0639\u064a\u0627\u062f\u0629"},
gai1(){return"\u0625\u0639\u0627\u062f\u0629 \u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0639\u064a\u0627\u062f\u0629"},
gaik(){return"\u062d\u0630\u0641 \u0627\u0644\u0639\u064a\u0627\u062f\u0629 \u0646\u0647\u0627\u0626\u064a\u064b\u0627"},
gaij(){return"\u0647\u0644 \u062a\u0631\u064a\u062f \u062d\u0630\u0641 \u0647\u0630\u0647 \u0627\u0644\u0639\u064a\u0627\u062f\u0629 \u0646\u0647\u0627\u0626\u064a\u064b\u0627\u061f"},
aih(a){return"\u0633\u064a\u062a\u0645 \u062d\u0630\u0641 "+a+" \u0646\u0647\u0627\u0626\u064a\u064b\u0627 \u0645\u0639 \u0643\u0644 \u0627\u0644\u0623\u0637\u0628\u0627\u0621 \u0627\u0644\u062a\u0627\u0628\u0639\u064a\u0646 \u0644\u0647\u0627\u060c \u0648\u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 \u0639\u0646 \u0630\u0644\u0643. \u064a\u064f\u0633\u0645\u062d \u0628\u0630\u0644\u0643 \u0641\u0642\u0637 \u0625\u0630\u0627 \u0644\u0645 \u064a\u0643\u0646 \u0644\u0647\u0630\u0647 \u0627\u0644\u0639\u064a\u0627\u062f\u0629 \u0623\u064a \u062d\u0627\u0644\u0627\u062a \u0623\u0648 \u0645\u062f\u0641\u0648\u0639\u0627\u062a \u0645\u0633\u062c\u0651\u0644\u0629\u060c \u0623\u0648 \u0625\u0630\u0627 \u0643\u0627\u0646 \u0647\u0630\u0627 \u0627\u0644\u0641\u0631\u0639 \u0644\u0627 \u064a\u0632\u0627\u0644 \u062c\u062f\u064a\u062f\u064b\u0627 \u2014 \u0648\u0625\u0644\u0627\u060c \u0642\u0645 \u0628\u0625\u0644\u063a\u0627\u0621 \u0627\u0644\u062a\u0641\u0639\u064a\u0644 \u0628\u062f\u0644\u0627\u064b \u0645\u0646 \u0630\u0644\u0643."},
gaii(){return"\u062a\u0645 \u062d\u0630\u0641 \u0627\u0644\u0639\u064a\u0627\u062f\u0629 \u0646\u0647\u0627\u0626\u064a\u064b\u0627."},
gUT(){return"\u063a\u064a\u0631 \u0646\u0634\u0637"},
akS(a){return"\u0627\u0644\u0623\u0633\u0639\u0627\u0631 \u2014 "+a},
gakR(){return"\u0627\u062a\u0631\u0643 \u0627\u0644\u062d\u0642\u0644 \u0641\u0627\u0631\u063a\u064b\u0627 \u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0633\u0639\u0631 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a \u0644\u0644\u0645\u0627\u062f\u0629. \u0627\u0644\u0642\u064a\u0645\u0629 \u0627\u0644\u0645\u062d\u0641\u0648\u0638\u0629 \u062a\u062e\u0635 \u0647\u0630\u0627 \u0627\u0644\u0637\u0628\u064a\u0628 \u0641\u0642\u0637."},
