gam9(){return"\u0625\u0636\u0627\u0641\u0629 \u0642\u0627\u0639\u062f\u0629 \u0637\u0628\u064a\u0628"},
gam0(){return"\u0642\u0627\u0639\u062f\u0629 \u0637\u0628\u064a\u0628"},
gam1(){return"\u0627\u0644\u0637\u0628\u064a\u0628"},
gam8(){return"\u0646\u0648\u0639 \u0627\u0644\u062d\u0627\u0644\u0629"},
gWn(){return"\u0643\u0644 \u0627\u0644\u0623\u0646\u0648\u0627\u0639"},
gam4(){return"\u0627\u0644\u0633\u0639\u0631 (\u0645\u0628\u0644\u063a \u0644\u0643\u0644 \u0648\u062d\u062f\u0629\u060c \u0623\u0648 \u0646\u0633\u0628\u0629 %)"},
gam3(){return"\u0628\u062f\u0648\u0646 \u062d\u062f \u0644\u0639\u062f\u062f \u0627\u0644\u0648\u062d\u062f\u0627\u062a \u0641\u064a \u0627\u0644\u062d\u0627\u0644\u0629"},
galZ(){return"\u0645\u0628\u0644\u063a \u0625\u0636\u0627\u0641\u064a \u0644\u0643\u0644 \u0637\u0644\u0628 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gam_(){return"...\u0625\u0630\u0627 \u0643\u0627\u0646 \u0627\u0644\u0637\u0644\u0628 \u0623\u0643\u062b\u0631 \u0645\u0646 (\u0648\u062d\u062f\u0629)"},
gam6(){return"\u0628\u062f\u0648\u0646 \u062d\u062f \u0644\u0644\u0648\u062d\u062f\u0627\u062a"},
gam2(){return"\u0627\u062e\u062a\u0631 \u0627\u0644\u0637\u0628\u064a\u0628 \u0648\u0627\u0643\u062a\u0628 \u0627\u0644\u0633\u0639\u0631 (\u0645\u062b\u0644\u0627\u064b 2000 \u0623\u0648 50%)."},
gamn(){return"\u0646\u0633\u0628\u0629 \u0645\u0646 \u0627\u0644\u0645\u0628\u0627\u0644\u063a \u0627\u0644\u0648\u0627\u0635\u0644\u0629 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gamm(){return"\u062a\u064f\u0636\u0627\u0641 \u0647\u0630\u0647 \u0627\u0644\u0646\u0633\u0628\u0629 \u0645\u0646 \u0643\u0644 \u0645\u0628\u0644\u063a \u064a\u0635\u0644 \u0645\u0646 \u0627\u0644\u0623\u0637\u0628\u0627\u0621 \u062e\u0644\u0627\u0644 \u0641\u062a\u0631\u0629 \u0631\u0627\u062a\u0628 \u0627\u0644\u0645\u0648\u0638\u0641 \u0625\u0644\u0649 \u0639\u0645\u0648\u0644\u062a\u0647. \u0627\u062a\u0631\u0643\u0647 \u0641\u0627\u0631\u063a\u0627\u064b \u0628\u062f\u0648\u0646."},
gano(){return"\u0627\u0644\u0631\u0627\u062a\u0628 \u062d\u062f \u0623\u062f\u0646\u0649 \u0645\u0636\u0645\u0648\u0646"},
gann(){return"\u0639\u0646\u062f \u0627\u0644\u062a\u0634\u063a\u064a\u0644: \u0627\u0644\u0645\u0648\u0638\u0641 \u064a\u0627\u062e\u0630 \u0627\u0644\u0631\u0627\u062a\u0628 \u0623\u0648 \u0627\u0644\u0639\u0645\u0648\u0644\u0629\u060c \u0623\u064a\u0647\u0645\u0627 \u0623\u0643\u062b\u0631 (\u0645\u0648 \u0627\u0644\u0627\u062b\u0646\u064a\u0646 \u0633\u0648\u0627). \u0645\u062b\u0644\u0627\u064b \u062d\u062f \u0623\u062f\u0646\u0649 500,000 \u06482,000 \u0644\u0644\u064a\u0648\u0646\u062a: 100 \u064a\u0648\u0646\u062a = 500,000\u060c \u0648300 \u064a\u0648\u0646\u062a = 600,000."},
am7(a){return a+" \u0644\u0644\u0648\u062d\u062f\u0629"},
am5(a,b){return"+"+a+" \u0625\u0630\u0627 \u0623\u0643\u062b\u0631 \u0645\u0646 "+b+" \u0648\u062d\u062f\u0629"},
ganq(){return"\u062a\u062d\u062f\u064a\u062f \u0646\u0633\u0628 \u0627\u0644\u0639\u0645\u0648\u0644\u0629 \u0644\u0643\u0644 \u0645\u0627\u062f\u0629"},
gan7(){return"\u0625\u0639\u0627\u062f\u0629 \u062a\u0639\u064a\u064a\u0646 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631"},
an0(a){return"\u0625\u0639\u0627\u062f\u0629 \u062a\u0639\u064a\u064a\u0646 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u2014 "+a},
gan2(){return"\u064a\u0639\u064a\u0651\u0646 \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u062c\u062f\u064a\u062f\u0629 \u0644\u062d\u0633\u0627\u0628 \u0647\u0630\u0627 \u0627\u0644\u0645\u0648\u0638\u0641 \u0641\u0648\u0631\u064b\u0627. \u0634\u0627\u0631\u0643\u0647\u0627 \u0645\u0639\u0647 \u0645\u0628\u0627\u0634\u0631\u0629 \u2014 \u0644\u0646 \u064a\u062a\u0645 \u0625\u0631\u0633\u0627\u0644 \u0628\u0631\u064a\u062f \u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a."},
gan4(){return"\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u062c\u062f\u064a\u062f\u0629"},
gan_(){return"\u062a\u0623\u0643\u064a\u062f \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631"},
gan3(){return"\u0643\u0644\u0645\u062a\u0627 \u0627\u0644\u0645\u0631\u0648\u0631 \u063a\u064a\u0631 \u0645\u062a\u0637\u0627\u0628\u0642\u062a\u064a\u0646"},
gan6(){return"\u064a\u062c\u0628 \u0623\u0644\u0627 \u062a\u0642\u0644 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0639\u0646 6 \u0623\u062d\u0631\u0641"},
an5(a){return"\u062a\u0645\u062a \u0625\u0639\u0627\u062f\u0629 \u062a\u0639\u064a\u064a\u0646 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631. \u0634\u0627\u0631\u0643\u0647\u0627 \u0645\u0639 "+a+" \u0645\u0628\u0627\u0634\u0631\u0629."},
