gahI(){return"\u0627\u0644\u0644\u0648\u0646 (\u0647\u064a\u0643\u0633\u060c \u0645\u062b\u0627\u0644: FFB8763F)"},
gago(){return"\u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062d\u0627\u0644\u0627\u062a"},
