gamj(){return"\u0646\u0627\u062a\u0648\u0627\u0646\u0631\u06ce\u062a \u062f\u06c6\u062e\u06cc \u06a9\u06cc\u06c6\u0633\u06a9 \u0628\u06c6 \u0647\u06d5\u0698\u0645\u0627\u0631\u06cc \u0628\u06d5\u0695\u06ce\u0648\u06d5\u0628\u06d5\u0631 \u0686\u0627\u0644\u0627\u06a9 \u0628\u06a9\u0631\u06ce\u062a \u2014 \u0647\u06d5\u0698\u0645\u0627\u0631\u06ce\u06a9\u06cc \u062c\u06cc\u0627\u0648\u0627\u0632\u06cc \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f \u0628\u06c6 \u0626\u0627\u0645\u06ce\u0631\u06cc \u06a9\u06cc\u06c6\u0633\u06a9 \u0628\u06d5\u06a9\u0627\u0631\u0628\u0647\u06ce\u0646\u06d5"},
