gamB(){return"\u0645\u0648\u0648\u0686\u06d5\u06cc \u0628\u0646\u06d5\u0695\u06d5\u062a\u06cc (\u062f\u06cc\u0646\u0627\u0631)"},
gamf(){return"\u0628\u06d5\u0695\u06ce\u0648\u06d5\u0628\u06d5\u0631 \u2014 \u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u0647\u06d5\u0698\u0645\u0627\u0631\u06cc \u0686\u0648\u0648\u0646\u06d5\u0698\u0648\u0648\u0631\u06d5\u0648\u06d5\u06cc \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f/\u067e\u0632\u06cc\u0634\u06a9\u06cc \u062a\u0631 \u062f\u0631\u0648\u0633\u062a \u0628\u06a9\u0627\u062a"},
gamY(){return"\u0686\u0648\u0648\u0646\u06d5\u0698\u0648\u0648\u0631\u06d5\u0648\u06d5\u06cc \u067e\u06c6\u0631\u062a\u06d5\u06b5"},
