gWr(){return"\u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc"},
gamS(){return"\u0646\u0627\u0648 \u067e\u06ce\u0648\u06cc\u0633\u062a\u06d5."},
gamG(){return"\u0626\u06cc\u0645\u06d5\u06cc\u0644 \u0648 \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u067e\u06ce\u0648\u06cc\u0633\u062a\u0646 \u0628\u06c6 \u0686\u0648\u0648\u0646\u06d5\u0698\u0648\u0648\u0631\u06d5\u0648\u06d5\u06cc \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06ce\u06a9\u06cc \u0646\u0648\u06ce."},
gamF(){return"\u0626\u06cc\u0645\u06d5\u06cc\u0644 \u0648 \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0647\u06d5\u0631\u062f\u0648\u0648\u06a9\u06cc\u0627\u0646 \u0628\u0646\u0648\u0648\u0633\u06d5 \u0628\u06c6 \u062f\u0631\u0648\u0633\u062a\u06a9\u0631\u062f\u0646\u06cc \u0686\u0648\u0648\u0646\u06d5\u0698\u0648\u0648\u0631\u06d5\u0648\u06d5 \u0626\u06ce\u0633\u062a\u0627\u060c \u06cc\u0627\u0646 \u0647\u06d5\u0631\u062f\u0648\u0648\u06a9\u06cc\u0627\u0646 \u0628\u06d5\u062a\u0627\u06b5 \u0628\u0647\u06ce\u06b5\u06d5\u0631\u06d5\u0648\u06d5 \u0628\u06c6 \u0632\u06cc\u0627\u062f\u06a9\u0631\u062f\u0646\u06cc \u062f\u0648\u0627\u062a\u0631"},
